#include <cassert>\n#include <iostream>\n#include <chrono>\n#include \"t81/axion/engine.hpp\"\n#include \"t81/axion/policy_engine.hpp\"\n#include \"t81/experimental/cog/promotion.hpp\"\n#include \"t81/experimental/cog/tier4/planner.hpp\"\n#include \"t81/experimental/cog/tier4/tier4_loop.hpp\"\n\nint main() {\n  [[maybe_unused]] auto engine = t81::axion::make_policy_engine(std::nullopt);\n  t81::cog::v1::Tier4Loop loop(\n      [&](const t81::axion::SyscallContext& ctx) { return engine->evaluate(ctx); });\n\n  std::cout << \"Starting Tier 4 Loop Closure validation...\\n\";\n\n  // Test 1: Basic observe-reflect-refine cycle\n  std::cout << \"Test 1: Basic cycle... \";\n  loop.observe(\"initial state observation\");\n  auto trace = loop.reflect();\n  assert(trace.goal == \"initialize\");\n  assert(trace.confidence == 1.0f);\n  loop.refine();\n  assert(loop.get_model().current_goal == \"execute\");\n  std::cout << \"PASS\\n\";\n\n  // Test 2: Recursive self-improvement safety bounds\n  std::cout << \"Test 2: Recursive improvement safety... \";\n  \n  // Test valid improvement\n  bool improvement_result = loop.attempt_recursive_improvement(\"self_optimization\");\n  assert(improvement_result);\n  assert(loop.get_model().confidence > 1.0f);\n  \n  // Test safety bounds enforcement\n  loop.get_model().confidence = 0.05f; // Below minimum threshold\n  improvement_result = loop.attempt_recursive_improvement(\"meta_learning\");\n  assert(!improvement_result); // Should be denied\n  \n  // Reset confidence for next test\n  loop.get_model().confidence = 0.9f;\n  std::cout << \"PASS\\n\";\n\n  // Test 3: Consecutive improvement limits\n  std::cout << \"Test 3: Consecutive improvement limits... \";\n  \n  // Attempt multiple improvements (should hit limit)\n  int successful_improvements = 0;\n  for (int i = 0; i < 5; ++i) {\n    if (loop.attempt_recursive_improvement(\"self_optimization\")) {\n      successful_improvements++;\n    }\n  }\n  \n  // Should be limited by max_consecutive_improvements (default: 3)\n  assert(successful_improvements <= 3);\n  std::cout << \"PASS (\" << successful_improvements << \" improvements allowed)\\n\";\n\n  // Test 4: Meta-learning determinism\n  std::cout << \"Test 4: Meta-learning determinism... \";\n  \n  // Reset to known state\n  loop.get_model().confidence = 0.8f;\n  loop.get_model().current_goal = \"test_meta_learning\";\n  loop.get_model().history.clear();\n  \n  // Perform meta-learning twice\n  bool ml1 = loop.attempt_recursive_improvement(\"meta_learning\");\n  float confidence_after_ml1 = loop.get_model().confidence;\n  \n  // Reset and repeat\n  loop.get_model().confidence = 0.8f;\n  loop.get_model().history.clear();\n  bool ml2 = loop.attempt_recursive_improvement(\"meta_learning\");\n  float confidence_after_ml2 = loop.get_model().confidence;\n  \n  // Results should be identical (deterministic)\n  assert(ml1 == ml2);\n  assert(std::abs(confidence_after_ml1 - confidence_after_ml2) < 1e-6f);\n  std::cout << \"PASS\\n\";\n\n  // Test 5: Safety score calculation\n  std::cout << \"Test 5: Safety score calculation... \";\n  \n  // Reset to safe state\n  loop.get_model().confidence = 1.0f;\n  \n  // Get reflection trace with safety score\n  auto safe_trace = loop.reflect();\n  assert(safe_trace.safety_score == 1.0f);\n  \n  // Lower confidence and check score penalty\n  loop.get_model().confidence = 0.3f;\n  auto risky_trace = loop.reflect();\n  assert(risky_trace.safety_score < 1.0f);\n  assert(risky_trace.safety_score > 0.7f); // Should not be too low\n  \n  std::cout << \"PASS (safe: \" << safe_trace.safety_score \n            << \", risky: \" << risky_trace.safety_score << \")\\n\";\n\n  // Test 6: Integration with promotion system\n  std::cout << \"Test 6: Promotion system integration... \";\n  \n  // Create low confidence trace to trigger promotion\n  t81::cog::v1::ReflectionTrace low_conf_trace;\n  low_conf_trace.confidence = 0.5f;\n  low_conf_trace.goal = \"recalibrate\";\n  low_conf_trace.reason = \"performance degradation detected\";\n  \n  // Should promote to Tier 4\n  bool should_promote = t81::cog::should_promote_to_tier4(low_conf_trace);\n  assert(should_promote);\n  \n  // High confidence trace should not promote\n  t81::cog::v1::ReflectionTrace high_conf_trace;\n  high_conf_trace.confidence = 0.95f;\n  high_conf_trace.goal = \"execute\";\n  high_conf_trace.reason = \"optimal performance\";\n  \n  should_promote = t81::cog::should_promote_to_tier4(high_conf_trace);\n  assert(!should_promote);\n  \n  std::cout << \"PASS\\n\";\n\n  // Test 7: TierAwarePlanner integration\n  std::cout << \"Test 7: TierAwarePlanner integration... \";\n  \n  using namespace t81::cog::v1;\n  \n  // Simple task should not use Tier 4\n  TaskMetadata simple_task{\"simple\", 5, 100, false};\n  assert(TierAwarePlanner::select_tier(simple_task) == t81::cog::TierId::Tier1);\n  \n  // Complex task requiring reflection should use Tier 4\n  TaskMetadata complex_task{\"complex\", 70, 1000, true};\n  assert(TierAwarePlanner::select_tier(complex_task) == t81::cog::TierId::Tier4);\n  \n  std::cout << \"PASS\\n\";\n\n  // Test 8: End-to-end loop closure\n  std::cout << \"Test 8: End-to-end loop closure... \";\n  \n  // Simulate complete cognitive cycle\n  loop.observe(\"complex problem detected\");\n  auto decision_trace = loop.reflect();\n  \n  if (decision_trace.confidence < 0.9f) {\n    loop.refine();\n    \n    // Attempt improvement if still needed\n    if (loop.get_model().confidence < 0.95f) {\n      loop.attempt_recursive_improvement(\"meta_learning\");\n    }\n  }\n  \n  // Verify loop completed successfully\n  assert(loop.get_model().history.size() > 0);\n  assert(loop.get_model().confidence > 0.8f);\n  \n  std::cout << \"PASS\\n\";\n\n  std::cout << \"\\n🎉 All Tier 4 Loop Closure tests passed!\\n\";\n  std::cout << \"✅ Observe-Reflect-Refine cycle validated\\n\";\n  std::cout << \"✅ Recursive self-improvement safety enforced\\n\";\n  std::cout << \"✅ Meta-learning determinism verified\\n\";\n  std::cout << \"✅ Integration with promotion system confirmed\\n\";\n  std::cout << \"✅ Tier 4 Loop successfully closed!\\n\";\n  \n  return 0;\n}
